const timelineBeforeHeadResize=renderTimeline;renderTimeline=function(){timelineBeforeHeadResize();document.querySelectorAll('.timeline-clip.scene[data-scene-index]').forEach(el=>{const s=project.scenes[+el.dataset.sceneIndex],edge=el.querySelector('.clip-edge.left');if(!s||!edge)return;edge.hidden=false;edge.title='Drag to trim or extend the scene beginning';edge.setAttribute('aria-label','Resize beginning of '+s.name);edge.onpointerdown=e=>{if(e.button||recording||window.editorTaskBusy)return;e.preventDefault();e.stopImmediatePropagation();stop();const x=e.clientX,start=s.duration,label=el.querySelector('.clip-name');let delta=0;edge.setPointerCapture(e.pointerId);timelineDrag={mode:'scene-head'};edge.onpointermove=event=>{delta=clamp(Math.round((event.clientX-x)/timelineZoom*20)/20,start-60,start-1);el.style.width=(start-delta)*timelineZoom+'px';el.style.transform='translateX('+delta*timelineZoom+'px)';label.textContent=s.name+' · '+(start-delta).toFixed(2)+'s'};const finish=cancel=>{edge.onpointermove=edge.onpointerup=edge.onpointercancel=null;timelineDrag=null;if(!cancel&&Math.abs(delta)>.001){try{const plan=planSceneHeadResize(s,delta);Object.assign(project,plan);time=Math.max(0,Math.min(current().duration,time-delta));save();hydrateAudio();toast('Scene beginning resized. Undo restores the original timing.')}catch(error){toast(error.message)}}render()};edge.onpointerup=()=>finish(false);edge.onpointercancel=()=>finish(true)};edge.addEventListener('pointerdown',e=>e.stopPropagation())})};
